optimization-iteration.patch:
diff --git a/tools/bot-evaluation/src/identity.rs b/tools/bot-evaluation/src/identity.rs
index 1861494b..edd37563 100644
--- a/tools/bot-evaluation/src/identity.rs
+++ b/tools/bot-evaluation/src/identity.rs
@@ -81,6 +81,7 @@ impl Serialize for Canonical<'_> {
             }
             Value::Null => serializer.serialize_none(),
             Value::String(s) => serializer.serialize_str(s),
+            Value::Bool(v) => serializer.serialize_str(if *v { "true" } else { "false" }),
             v => serializer.serialize_str(&v.to_string()),
         }
     }
